# A dictionary is like a labeled notebook where each key points to a value.
PROJECT_QUEUES = [
    {
        "key": "restaurant_management_system",
        "title": "Restaurant Management System",
        # Each tuple holds (relative_file_path, starter_file_content).
        "files": [
            (
                "README.md",
                "# Restaurant Management System\nStarter blueprint generated by CLEMOH.\n",
            ),
            (
                "app.py",
                "def main():\n    print('Restaurant Management System ready!')\n\n\nif __name__ == '__main__':\n    main()\n",
            ),
        ],
    }
]

ALL_TOPICS = [
    {
        "key": project["key"],
        "title": project["title"],
    }
    for project in PROJECT_QUEUES
]


def get_project_blueprint(project_key):
    # Loop through every project in PROJECT_QUEUES to find a matching key.
    for project in PROJECT_QUEUES:
        if project["key"] == project_key:
            return project

    # If no matching key is found, return the first blueprint as a safe fallback.
    return PROJECT_QUEUES[0]
